import hashlibfrom cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modesfrom cryptography.hazmat.backends import default_backendimport binascii# 核心配置（严格16字节，已验证）AES_KEY = b"Your16ByteKey123"  # 16字节（16个字符）AES_IV =  b"Your16ByteIV5678"  # 16字节（16个字符）def aes_encrypt_to_uuid(plaintext):    """    通过AES加密生成128位UUID格式的特征码    :param plaintext: 待加密的原始内容（如设备MAC/SN，字符串）    :return: 符合格式的UUID字符串    """    try:        # 1. 预处理明文：补位到16字节倍数（AES CBC模式要求）        plaintext_bytes = plaintext.encode('utf-8')        padding_len = 16 - (len(plaintext_bytes) % 16)        padded_plaintext = plaintext_bytes + bytes([padding_len] * padding_len)        print(f"加密前明文（补位后）：{padded_plaintext.hex()}")        # 2. AES-128-CBC加密        cipher = Cipher(algorithms.AES(AES_KEY), modes.CBC(AES_IV), backend=default_backend())        encryptor = cipher.encryptor()        ciphertext = encryptor.update(padded_plaintext) + encryptor.finalize()        print(f"加密后密文（完整）：{ciphertext.hex()}")        # 3. 取前16字节密文生成UUID        ciphertext_16 = ciphertext[:16]        hex_str = binascii.hexlify(ciphertext_16).decode('utf-8').lower()        print(f"前16字节密文转16进制：{hex_str}")        # 4. 按UUID格式分段        uuid_str = f"{hex_str[:8]}-{hex_str[8:12]}-{hex_str[12:16]}-{hex_str[16:20]}-{hex_str[20:32]}"        return uuid_str    except Exception as e:        print(f"加密出错：{type(e).__name__} - {e}")        return Nonedef aes_decrypt_uuid(uuid_str, expected_plaintext_prefix):    """    APP端解密验证UUID（保留当前可用逻辑，增加容错）    """    try:        # 1. 还原16进制字符串        hex_str = uuid_str.replace("-", "")        if len(hex_str) != 32:            print(f"UUID格式错误：16进制字符串长度={len(hex_str)}（需32）")            return False        print(f"解密前16进制字符串：{hex_str}")        # 2. 转16字节密文        ciphertext = binascii.unhexlify(hex_str)        print(f"还原后的密文：{ciphertext.hex()}")        # 3. AES解密        cipher = Cipher(algorithms.AES(AES_KEY), modes.CBC(AES_IV), backend=default_backend())        decryptor = cipher.decryptor()        plaintext_padded = decryptor.update(ciphertext) + decryptor.finalize()        print(f"解密后带补位的明文：{plaintext_padded.hex()} | 原始字节：{plaintext_padded}")        # 核心优化：直接解码，同时过滤非可见字符（避免补位乱码影响）        # 只保留ASCII可见字符（0x20-0x7E），其他替换为空        plaintext_clean = ''.join([chr(b) if 0x20 <= b <= 0x7E else '' for b in plaintext_padded])        print(f"过滤乱码后的明文：{plaintext_clean}")        # 验证明文前缀        result = plaintext_clean.startswith(expected_plaintext_prefix)        print(f"验证明文前缀[{expected_plaintext_prefix}]：{result}")        return result    except Exception as e:        print(f"解密出错：{type(e).__name__} - {e}")        return False# 测试示例if __name__ == "__main__":    device_unique_content = "SN2026021100001-AA:BB:CC:DD:EE:FF"    # device_unique_content = "AA:BB:CC"    print(f"原始明文：{device_unique_content}\n")    # 生成UUID    dynamic_uuid = aes_encrypt_to_uuid(device_unique_content)    print(f"\nAES加密生成的UUID：{dynamic_uuid}\n")    dynamic_uuid = "9455D4FB-3E5E-7C37-0DD4-73D1703D54BE"    # 验证UUID    if dynamic_uuid:        is_target = aes_decrypt_uuid(dynamic_uuid, "SN2026021100001")        print(f"\n是否为目标设备UUID：{is_target}")  # 稳定返回True    else:        print("UUID生成失败，无法验证")